\begin{proposition}\label{prop:adj}
$i:B_P\to A_P$ has right adjoint $\varphi:A_P\to B_P$, $T\mapsto B(T)$.
Hence the pointwise left Kan extension is $\Lan_iF=F\circ\varphi=:G_F$,
$G_F(T)=F(B(T))$, and for $b\in B_P$, $B(i(b))=b$, so
$(\Lan_iF)(i(b))=F(b)$.
\end{proposition}

\begin{proof}
$\operatorname{Hom}_{A_P}(i(P\to P/F),T)$ is a singleton iff
$F\subseteq\Phi_T$, else empty (Proposition~\ref{prop:faces}(b)); the same
holds for $\operatorname{Hom}_{B_P}((P\to P/F),(P\to P/\Phi_T))$; naturality
is by uniqueness. Kan extension along a functor with right adjoint is
precomposition with the adjoint (unit/counit); pointwise: $(i\downarrow T)$
has terminal object $B(T)$.
\end{proof}

\begin{proposition}[Separation]\label{prop:sep}
For every cover $R=\{T\to T_i\}$ and every $F$, the map
$G_F(T)\to\prod_iG_F(T_i)$ is injective.
